// The menu bar icon: the emu face from the app icon, black on a light menu bar and white (with dark
// eyes and beak) on a dark or selected one. The masks are generated by tool/menu_icon.swift and copied
// into Contents/Resources by `emu app install`; without them the app keeps an SF Symbol.
import Cocoa

enum MenuIcon {
    static let size = NSSize(width: 18, height: 18)

    /// Contents/Resources of the running bundle, found from the executable (works before Info.plist exists).
    static var resources: URL? {
        Bundle.main.executableURL?.deletingLastPathComponent().deletingLastPathComponent()
            .appendingPathComponent("Resources")
    }

    /// One 18pt mask with its @1x and @2x pixels, or nil when a file is missing or unreadable.
    static func mask(_ name: String, in dir: URL) -> NSImage? {
        let img = NSImage(size: size)
        for file in ["\(name).png", "\(name)@2x.png"] {
            guard let rep = NSImageRep(contentsOf: dir.appendingPathComponent(file)) else { return nil }
            rep.size = size
            img.addRepresentation(rep)
        }
        return img
    }

    /// The icon, or nil when the masks are not there. Not a template image: a template only inverts
    /// the black ink, which gives a hollow-eyed face on a dark menu bar, so each appearance has its own
    /// mask, already in its color, picked whenever the button draws.
    static func load(from dir: URL? = resources) -> NSImage? {
        guard let dir = dir, let light = mask("MenuIcon", in: dir), let dark = mask("MenuIconDark", in: dir) else { return nil }
        let img = NSImage(size: size, flipped: false) { rect in
            let isDark = NSAppearance.currentDrawing().bestMatch(from: [.aqua, .darkAqua]) == .darkAqua
            (isDark ? dark : light).draw(in: rect)
            return true
        }
        img.accessibilityDescription = "emu"
        return img
    }

    /// The icon `load` gives, or the SF Symbol the app used before.
    static func image(from dir: URL? = resources) -> NSImage? {
        load(from: dir) ?? NSImage(systemSymbolName: "iphone.gen3", accessibilityDescription: "emu")
    }

    // ---- self test --------------------------------------------------------------

    /// Renders the icon in both appearances when the masks are bundled (`emu app install` copies them
    /// before running this); a bare binary (CI) only checks the fallback.
    static func selfTest(resources dir: URL? = resources) -> Int {
        var failures = 0
        func check(_ ok: Bool, _ what: String) {
            if !ok { failures += 1; print("✗ \(what)") }
        }
        let nowhere = URL(fileURLWithPath: "/nonexistent-emu-menu-icon")
        check(load(from: nowhere) == nil, "no masks, no icon")
        check(image(from: nowhere) != nil, "no masks, SF Symbol fallback")
        if let dir = dir, FileManager.default.fileExists(atPath: dir.appendingPathComponent("MenuIcon.png").path) {
            if let icon = load(from: dir) {
                // The middle of the forehead: black ink on a light bar, white face on a dark one.
                check(pixel(icon, .aqua).map { $0.a > 0.8 && $0.l < 0.2 } == true, "light menu bar: black face")
                check(pixel(icon, .darkAqua).map { $0.a > 0.8 && $0.l > 0.8 } == true, "dark menu bar: white face")
            } else {
                check(false, "the bundled menu icon loads")
            }
            print(failures == 0 ? "✓ menu icon self-test passed" : "\(failures) failure(s)")
        } else {
            print(failures == 0 ? "✓ menu icon self-test passed (not bundled: SF Symbol)" : "\(failures) failure(s)")
        }
        return failures
    }

    /// Draws `icon` at @2x under `appearance` and reads the forehead pixel (alpha, luminance).
    private static func pixel(_ icon: NSImage, _ appearance: NSAppearance.Name) -> (a: CGFloat, l: CGFloat)? {
        guard let look = NSAppearance(named: appearance),
              let rep = NSBitmapImageRep(bitmapDataPlanes: nil, pixelsWide: 36, pixelsHigh: 36, bitsPerSample: 8,
                                         samplesPerPixel: 4, hasAlpha: true, isPlanar: false, colorSpaceName: .deviceRGB,
                                         bytesPerRow: 0, bitsPerPixel: 0) else { return nil }
        rep.size = size // 18pt at 36px, set before the context reads it
        guard let ctx = NSGraphicsContext(bitmapImageRep: rep) else { return nil }
        look.performAsCurrentDrawingAppearance {
            NSGraphicsContext.saveGraphicsState()
            NSGraphicsContext.current = ctx
            icon.draw(in: NSRect(origin: .zero, size: size))
            NSGraphicsContext.restoreGraphicsState()
        }
        guard let c = rep.colorAt(x: 18, y: 12)?.usingColorSpace(.deviceRGB) else { return nil }
        return (c.alphaComponent, (c.redComponent + c.greenComponent + c.blueComponent) / 3)
    }
}
